export const postal: string = "<!DOCTYPE html>\n<html>\n<head>\n\n\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<script src=\"./support.js\"></script>\n</head>\n<body>\n<x-dc>\n<helmet>\n<title>Postal · Open House Claudio Coello 38</title>\n<meta name=\"omelette-owns-print\" content=\"1\">\n<link href=\"https://fonts.googleapis.com/css2?family=Hanken+Grotesk:wght@300;400;500&family=Cormorant+Garamond:ital,wght@1,400&display=swap\" rel=\"stylesheet\">\n<script src=\"/open-house/_rt/qrcode.js\"></script>\n<style>\n*{box-sizing:border-box;-webkit-font-smoothing:antialiased;}\nhtml,body{margin:0;background:#e9e5e0;}\na{color:#161616;text-decoration:none;}\na:hover{color:#8c6a55;}\n@page{size:148mm 210mm;margin:0;}\n@media print{html,body{background:#fff;}[data-noprint]{display:none !important;}[data-sheet-wrap]{padding:0 !important;}[data-sheet]{box-shadow:none !important;}}\n</style>\n</helmet>\n<div data-sheet-wrap=\"\" style=\"min-height:100vh;display:flex;flex-direction:column;align-items:center;gap:20px;padding:32px 16px;font-family:'Hanken Grotesk',sans-serif;color:#161616;\">\n  <div data-noprint=\"\" style=\"display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:12px;\">\n    <span style=\"font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:#7a746e;\">Postal · {{ name }} · A5</span>\n    <button type=\"button\" onClick=\"{{ doPrint }}\" style=\"appearance:none;border:0;background:#161616;color:#fff;font:inherit;font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;padding:11px 16px;cursor:pointer;\">Guardar PDF / Imprimir</button>\n  </div>\n  <div data-sheet=\"\" style=\"width:148mm;height:210mm;background:#fff;box-shadow:0 20px 50px -20px rgba(22,22,22,.35);padding:13mm 12mm 12mm;display:flex;flex-direction:column;gap:7mm;overflow:hidden;\">\n    <img src=\"assets/isotipo.png\" alt=\"Forma Prima\" style=\"height:7mm;width:auto;align-self:flex-start;\">\n    <sc-if value=\"{{ found }}\" hint-placeholder-val=\"{{ true }}\">\n      <div style=\"display:flex;justify-content:space-between;align-items:flex-start;gap:8mm;\">\n        <div style=\"display:flex;flex-direction:column;gap:4.2mm;font-size:9.5pt;line-height:1.45;min-width:0;\">\n          <span style=\"font-family:'Cormorant Garamond',serif;font-style:italic;font-size:14pt;line-height:1.2;\">{{ salutation }}</span>\n          <span style=\"text-transform:uppercase;\">Open House<br>Claudio Coello 38, 2º dcha.</span>\n          <span>Jueves 8 de octubre<br>Madrid<br>{{ formatLine }}</span>\n          <sc-if value=\"{{ hasOthers }}\"><span style=\"color:#5f5953;\">{{ othersLine }}</span></sc-if>\n          <span style=\"display:flex;flex-direction:column;gap:1mm;\">\n            <span style=\"text-transform:uppercase;\">{{ ctaLine }} →</span>\n            <a href=\"{{ link }}\" style=\"font-size:8pt;color:#8c6a55;word-break:break-all;\">{{ linkLabel }}</a>\n          </span>\n          <span style=\"font-size:8pt;color:#5f5953;\">Rogamos confirmación antes del martes 6 de octubre.</span>\n        </div>\n        <div style=\"display:flex;flex-direction:column;align-items:center;gap:1.5mm;flex:none;\">\n          <div ref=\"{{ qrRef }}\" style=\"width:22mm;height:22mm;\"></div>\n          <span style=\"font-size:6pt;letter-spacing:.14em;text-transform:uppercase;color:#7a746e;\">Escanea</span>\n        </div>\n      </div>\n    </sc-if>\n    <sc-if value=\"{{ notFound }}\">\n      <span style=\"font-size:10pt;color:#7a746e;\">Invitación no encontrada. Ábrela desde el panel del estudio.</span>\n    </sc-if>\n    <div style=\"flex:1;min-height:0;display:flex;flex-direction:column;gap:1.5mm;\"><img src=\"assets/cc38-3943.webp\" alt=\"Comedor de Claudio Coello 38\" style=\"flex:1;min-height:0;width:100%;object-fit:cover;display:block;\"><span style=\"font-size:6pt;letter-spacing:.12em;text-transform:uppercase;color:#7a746e;align-self:flex-end;\">Fotografía · Yuichi Kimura</span></div>\n  </div>\n</div>\n</x-dc>\n<script type=\"text/x-dc\" data-dc-script>\nclass Component extends DCLogic {\n  state = { data: null };\n  qrRef = React.createRef();\n  componentDidMount() {\n    const d = (window.__OH && window.__OH.datos) || { groups: [] };\n    this.setState({ data: d }, () => {\n      this.drawQr();\n      if (new URLSearchParams(location.search).has('print')) {\n        const go = () => setTimeout(() => window.print(), 700);\n        if (document.readyState === 'complete') go(); else window.addEventListener('load', go, { once: true });\n      }\n    });\n  }\n  componentDidUpdate() { this.drawQr(); }\n  info() {\n    const p = new URLSearchParams(location.search);\n    const token = p.get('i') || '';\n    const base = (p.get('b') || this.props.baseUrl || 'https://formaprima.es/cc38').replace(/\\/$/, '');\n    let guest = null, group = null;\n    ((this.state.data || {}).groups || []).forEach(g => g.members.forEach(m => { if (m.token === token) { guest = m; group = g; } }));\n    return { token, link: base + '/' + token, guest, group };\n  }\n  drawQr() {\n    const el = this.qrRef.current, { link, guest } = this.info();\n    if (!el || !guest || !window.qrcode || el.dataset.link === link) { if (el && !window.qrcode && !this._retry) { this._retry = setTimeout(() => { this._retry = null; this.drawQr(); }, 300); } return; }\n    const q = window.qrcode(0, 'M'); q.addData(link); q.make();\n    el.innerHTML = q.createSvgTag({ cellSize: 2, margin: 0, scalable: true });\n    const svg = el.querySelector('svg'); if (svg) { svg.style.width = '100%'; svg.style.height = '100%'; svg.style.display = 'block'; }\n    el.dataset.link = link;\n  }\n  renderVals() {\n    const { link, guest, group } = this.info();\n    const loaded = !!this.state.data;\n    if (!guest) return { found: !loaded, notFound: loaded, name: '', qrRef: this.qrRef, doPrint: () => window.print() };\n    const others = group.members.filter(m => m.id !== guest.id).map(m => m.name);\n    const join = a => a.length < 2 ? (a[0] || '') : a.slice(0, -1).join(', ') + ' y ' + a[a.length - 1];\n    return {\n      found: true, notFound: false, name: guest.name, qrRef: this.qrRef,\n      salutation: `${guest.name},`,\n      formatLine: group.exclusive ? 'Visita privada, en exclusiva.' : 'Turnos reducidos y compartidos. Invitación personal e intransferible.',\n      hasOthers: others.length > 0, othersLine: `Invitación conjunta con ${join(others)}.`,\n      ctaLine: group.booking ? 'Tu visita' : 'Reserva tu horario',\n      link, linkLabel: link.replace(/^https?:\\/\\//, ''),\n      doPrint: () => window.print()\n    };\n  }\n}\n</script>\n</body>\n</html>\n"
